#!/bin/sh
# Differential test of the SPARK Unishox2 port against the C reference.
#  1. builds reference/unishox2.c with clang into tests/build/libunishox2_ref.a;
#  2. builds the test twice: against the library with all run-time checks and contracts
#     enabled (mode checks), and against the release code (mode bench: -O2 -gnatp -gnatn,
#     the code that ships, without the partition-wide restrictions);
#  3. runs each on the fixed corpus (tests/corpus.txt, regenerated by gen_corpus.py),
#     N random round trips and N decoder fuzz cases (fixed seed), and checks that the two
#     runs print the same.
# Usage: tests/run.sh [round trips (default 100000)] [decoder fuzz cases (default 100000)]
set -eu
HERE=$(cd "$(dirname "$0")" && pwd)
ROOT=$(dirname "$HERE")
. "$ROOT/env.sh"
B="$HERE/build"
mkdir -p "$B"

python3 -I "$HERE/gen_corpus.py" > "$B/corpus.txt"
if ! cmp -s "$B/corpus.txt" "$HERE/corpus.txt"; then
  echo "tests/corpus.txt is out of date with gen_corpus.py" >&2; exit 1
fi

"$HERE/build-ref.sh"

for mode in checks bench; do
  gprbuild -q -p -P "$HERE/tests.gpr" -XUNISHOX_BUILD_MODE=$mode > "$B/build-$mode.log" 2>&1 \
    || { grep -v 'deployment version' "$B/build-$mode.log"; exit 1; }
done
for mode in checks bench; do
  echo "== library mode $mode"
  "$B/$mode/test_unishox" "$HERE/corpus.txt" "${1:-100000}" "${2:-100000}" \
    | tee "$B/out-$mode.txt"
  grep -q '^PASS$' "$B/out-$mode.txt" || exit 1   # the exit status is lost in the pipe
done
if ! cmp -s "$B/out-checks.txt" "$B/out-bench.txt"; then
  echo "FAIL: the checks and bench builds print different results" >&2
  diff "$B/out-checks.txt" "$B/out-bench.txt" >&2 || true
  exit 1
fi
echo "checks and bench builds agree"
